/**
 * Parsing of model-drafted MiL examples.
 *
 * The examples are a DRAFT: generated by a model from the definition alone and
 * awaiting human review before anything is frozen into the conversion prompt.
 * Nothing here is authoritative MiL specification — mil-spec §3 keeps that
 * distinction.
 *
 * Two shapes occur in practice (measured 2026-10-14): blocks under `### 例 N`
 * headings, and bare `依頼:` / `MiL:` pairs with the headings dropped. Both are
 * accepted. A pair without a `MiL:` line keeps `mil: undefined`, so a malformed
 * draft stays visible in review instead of being guessed.
 */

/** Uppercase ASCII fence opening, e.g. ```text or ```. */
const FENCE_OPEN = /^```[^\n]*$/u

/**
 * @param {string} text
 * @returns {Array<{ index: number, request?: string, mil?: string }>}
 */
export function parseExamples(text) {
  if (typeof text !== 'string') throw new TypeError('parseExamples: text must be a string')

  /** @type {Array<{ index: number, request?: string, mil?: string, collecting?: boolean }>} */
  const found = []
  let current
  const lines = text.split('\n')

  const startEntry = (index) => {
    current = { index: index ?? found.length + 1 }
    found.push(current)
    return current
  }

  for (const line of lines) {
    const trimmed = line.trim()

    const heading = /^###\s*例\s*(\d+)\s*$/u.exec(trimmed)
    if (heading) {
      startEntry(Number.parseInt(heading[1], 10))
      continue
    }

    const request = /^依頼:\s*(.*)$/u.exec(trimmed)
    if (request) {
      if (current === undefined || current.request !== undefined || current.mil !== undefined) startEntry()
      current.request = request[1].trim() || undefined
      current.collecting = false
      continue
    }

    const mil = /^MiL:\s*(.*)$/u.exec(trimmed)
    if (mil) {
      if (current === undefined) startEntry()
      current.mil = mil[1].trim() || undefined
      current.collecting = true
      continue
    }

    if (current?.collecting === true) {
      if (trimmed.length === 0) {
        current.collecting = false
        continue
      }
      if (current.inFence === true) {
        if (trimmed === '```') {
          current.mil = current.buffer.join('\n').trim()
          current.buffer = undefined
          current.inFence = false
          current.collecting = false
          continue
        }
        current.buffer.push(line)
        continue
      }
      if (FENCE_OPEN.test(trimmed)) {
        current.inFence = true
        current.buffer = []
        continue
      }
      if (trimmed === '```') {
        // A closing fence with no opening one: the block ended.
        current.collecting = false
        continue
      }
      current.mil = current.mil === undefined ? trimmed : `${current.mil}\n${trimmed}`
    }
  }

  return found.map((entry) => {
    const value = { index: entry.index }
    if (entry.request !== undefined) value.request = entry.request
    if (entry.mil !== undefined) value.mil = unwrapFence(entry.mil)
    return value
  })
}

/** Unwrap a value that arrived as a single fenced block. */
function unwrapFence(value) {
  const match = /^```[^\n]*\n([\s\S]*?)\n?```$/u.exec(value.trim())
  return (match ? match[1] : value).trim()
}

/** Examples that carry both halves, ready for review. */
export function completeExamples(examples) {
  return examples.filter((entry) => typeof entry.request === 'string' && typeof entry.mil === 'string')
}
